334			t.Fatal(err)
335		}
336		otherIn := approvalApply()
337		otherIn.PolicyID = "p-other"
338		otherIn.RequestID = "ro1"
339		if _, err := w.Apply(otherIn); err != nil {
340			t.Fatal(err)
341		}
