378		// 终态记录不改写。
379		if r, _ := w.Request("u1", "r1"); r.State != RequestRejected || r.RejectReason != "manual no" {
380			t.Fatalf("rejected rewritten: %+v", r)
381		}
382		if r, _ := w.Request("u1", "r2"); r.State != RequestSettled || r.ActualFee != 8 {
383			t.Fatalf("settled rewritten: %+v", r)
384		}
385		if r, _ := w.Request("u1", "r3"); r.State != RequestCancelled {
386			t.Fatalf("cancelled rewritten: %+v", r)
387		}
388		// 另一条策略的待审批请求保持可批准。
389		if r, _ := w.Request("u1", "ro1"); r.State != RequestPendingApproval {
390			t.Fatalf("other policy request state = %v", r.State)
391		}
392		if _, err := w.Approve("u1", "ro1", "sa", "dev-approve"); err != nil {
393			t.Fatalf("other policy pending should still be approvable: %v", err)
394		}
395		if pv, _ := w.Policy("p-other"); pv.Deactivated {
396			t.Fatal("other policy should stay active")
397		}
398	}
