430	func TestDeactivateIdempotentAndConflict(t *testing.T) {
431		w, _ := setupDeactivate(t)
432		if _, err := w.Apply(approvalApply()); err != nil {
433			t.Fatal(err)
434		}
435	
436		first, err := w.DeactivatePolicy("p-approval", "sa", "dev-approve", "first reason")
437		if err != nil {
438			t.Fatal(err)
439		}
440		before := len(w.Ledger())
441	
442		// 理由带首尾空白，trim 后相同：返回首次结果，不留痕、不改写。
443		again, err := w.DeactivatePolicy("p-approval", "sa", "dev-approve", "  first reason\n")
444		if err != nil {
445			t.Fatalf("idempotent deactivate: %v", err)
446		}
447		if !again.DeactivatedAt.Equal(first.DeactivatedAt) || again.DeactivateReason != "first reason" {
448			t.Fatalf("repeat result differs: %+v vs %+v", again, first)
449		}
450		if len(w.Ledger()) != before {
451			t.Fatal("ledger grew on idempotent deactivate")
452		}
453		// 首次信息未被改写。
454		pv, _ := w.Policy("p-approval")
455		if pv.DeactivateReason != "first reason" {
456			t.Fatalf("first reason rewritten: %q", pv.DeactivateReason)
457		}
458	
459		// 理由不同：冲突，仍不留痕、不改写。
460		if _, err := w.DeactivatePolicy("p-approval", "sa", "dev-approve", "second reason"); !errors.Is(err, ErrConflict) {
461			t.Fatalf("different reason err = %v, want ErrConflict", err)
462		}
463		if len(w.Ledger()) != before {
464			t.Fatal("ledger grew on conflicting deactivate")
465		}
466		pv, _ = w.Policy("p-approval")
467		if pv.DeactivateReason != "first reason" {
468			t.Fatalf("first reason overwritten: %q", pv.DeactivateReason)
469		}
470	
471		// 再次停用仍须通过会话校验。
472		if _, err := w.DeactivatePolicy("p-approval", "s1", "dev1", "first reason"); !errors.Is(err, ErrNotPolicyOwner) {
473			t.Fatalf("repeat with bad session err = %v, want ErrNotPolicyOwner", err)
474		}
475		if _, err := w.DeactivatePolicy("p-approval", "nope", "dev-approve", "first reason"); !errors.Is(err, ErrNotPolicyOwner) {
476			t.Fatalf("repeat with missing session err = %v, want ErrNotPolicyOwner", err)
477		}
478		if len(w.Ledger()) != before {
479			t.Fatal("ledger grew on unauthorized repeat")
480		}
481		// 待审批请求只被拒绝一次。
482		if countKind(w.Ledger(), LedgerRejection) != 1 {
483			t.Fatal("pending request was rejected more than once")
484		}
485	}
