1207	// ---- 策略共享累计额度 ----
1208	
1209	// quotaReqSpec 描述累计额度测试备份中的一条请求。
1210	type quotaReqSpec struct {
1211		id           string
1212		account      string // "u1" 或 "u2"
1213		estFee       int64
1214		actualFee    int64
1215		state        RequestState
1216		due          bool   // 已预留请求的截止时刻是否早于恢复时刻 t0
1217		wasReserved  bool   // RequestCancelled 时标识“已预留后取消”
1218		rejectReason string // RequestRejected 使用
1219	}
1220	
1221	// quotaPolicySpec 描述一条策略及其请求。
1222	type quotaPolicySpec struct {
1223		id                    string
1224		per, total, threshold int64
1225		wait, reserveDur      time.Duration
1226		reqs                  []quotaReqSpec
1227	}
1228	
1229	// buildCumulativeQuotaBackup 构造资金完全自洽的备份：账户预留余额、各策略
1230	// 预留/已花费总额均按“现存已预留请求的预估费用”和“已结算请求的实际费用”
1231	// 求和填写，因此余额与各项总额核对必然通过，能否恢复只取决于累计额度判断。
1232	func buildCumulativeQuotaBackup(t *testing.T, t0 time.Time, policies []quotaPolicySpec) []byte {
1233		t.Helper()
1234		b := backupV1{
1235			Version:    backupVersion,
1236			ExportedAt: timeJSON(t0),
1237			Accounts: []accountBackupV1{
1238				{ID: "payer", Available: 0, Reserved: 0, CreatedAt: timeJSON(t0)},
1239				{ID: "u1", Available: 0, Reserved: 0, CreatedAt: timeJSON(t0)},
1240				{ID: "u2", Available: 0, Reserved: 0, CreatedAt: timeJSON(t0)},
1241			},
1242			Sessions: []sessionBackupV1{
1243				{ID: "s1", AccountID: "u1", DeviceID: "d1", ExpiresAt: timeJSON(t0.Add(24 * time.Hour)), CreatedAt: timeJSON(t0)},
1244				{ID: "s2", AccountID: "u2", DeviceID: "d2", ExpiresAt: timeJSON(t0.Add(24 * time.Hour)), CreatedAt: timeJSON(t0)},
1245			},
1246			Policies: make([]policyBackupV1, 0, len(policies)),
1247			Requests: make([]requestBackupV1, 0),
1248			Ledger:   []ledgerEntryBackupV1{},
1249		}
1250		sessionOf := map[string]string{"u1": "s1", "u2": "s2"}
1251	
1252		var accountReserved int64
1253		for _, ps := range policies {
1254			var reservedTotal, spentTotal int64
1255			b.Policies = append(b.Policies, policyBackupV1{
1256				ID: ps.id, PayerAccountID: "payer", AllowedAccountIDs: []string{"u1", "u2"},
1257				Operation: "charge", Payee: "shop",
1258				StartsAt: timeJSON(t0.Add(-time.Hour)), EndsAt: timeJSON(t0.Add(24 * time.Hour)),
1259				MaxPerRequest:      ps.per,
1260				MaxTotal:           ps.total,
1261				ApprovalThreshold:  ps.threshold,
1262				ApprovalWait:       durationJSON(ps.wait),
1263				MaxReserveDuration: durationJSON(ps.reserveDur),
1264			})
1265			for _, rs := range ps.reqs {
1266				// 待审批系请求统一提交于 t0；发生过预留的“到期”请求（恢复时已到
1267				// 预留截止或已预留超时）提交与预留时刻前移，保证预留时刻不会早于
1268				// 提交时刻。
1269				createdAt := t0
1270				if (rs.state == RequestReserved && rs.due) || rs.state == RequestReservationExpired {
1271					createdAt = t0.Add(-2 * ps.reserveDur)
1272				}
1273				r := requestBackupV1{
1274					PolicyID: ps.id, RequestID: rs.id, AccountID: rs.account, PayerAccountID: "payer",
1275					SessionID: sessionOf[rs.account], Operation: "charge", Payee: "shop",
1276					EstimatedFee: rs.estFee, ActualFee: rs.actualFee,
1277					State:     int(rs.state),
1278					CreatedAt: timeJSON(createdAt),
1279				}
1280				reservedOrigin := rs.state == RequestReserved || rs.state == RequestSettled ||
1281					rs.state == RequestReservationExpired ||
1282					(rs.state == RequestCancelled && rs.wasReserved)
1283				switch rs.state {
1284				case RequestPendingApproval, RequestRejected, RequestExpired:
1285					r.WaitDeadline = timeJSON(t0.Add(ps.wait))
1286				case RequestCancelled:
1287					if !reservedOrigin {
1288						r.DecidedAt = timeJSON(t0)
1289					}
1290				}
1291				if rs.state == RequestRejected {
1292					r.DecidedAt = timeJSON(t0)
1293					r.RejectReason = rs.rejectReason
1294				}
1295				if rs.state == RequestExpired {
1296					r.DecidedAt = timeJSON(t0.Add(ps.wait))
1297				}
1298				if reservedOrigin {
1299					reservedAt := createdAt
1300					r.ReservedAt = timeJSON(reservedAt)
1301					r.ReserveDuration = durationJSON(ps.reserveDur)
1302					if ps.reserveDur > 0 {
1303						r.ReserveDeadline = timeJSON(reservedAt.Add(ps.reserveDur))
1304					}
1305					if ps.threshold > 0 && rs.estFee > ps.threshold {
1306						// 批准路径：批准（预留）时刻不早于提交时刻、严格早于等待
1307						// 截止时刻，等待截止与三者最早值一致。
1308						r.ApproverAccountID = "payer"
1309						r.DecidedAt = timeJSON(reservedAt)
1310						r.WaitDeadline = timeJSON(createdAt.Add(ps.wait))
1311					}
1312				}
1313				if rs.state == RequestSettled {
1314					// 结算必须发生在有效预留期内：启用超时时取预留窗口中点（严格
1315					// 早于截止时刻）；关闭超时时在预留完成时刻结算即合法。
1316					if ps.reserveDur > 0 {
1317						r.SettledAt = timeJSON(time.Time(r.ReservedAt).Add(ps.reserveDur / 2))
1318					} else {
1319						r.SettledAt = r.ReservedAt
1320					}
1321				}
1322				if rs.state == RequestReservationExpired {
1323					r.ReserveExpiredAt = r.ReserveDeadline
1324				}
1325				b.Requests = append(b.Requests, r)
1326	
1327				switch rs.state {
1328				case RequestReserved:
1329					sum, ok := addInt64(reservedTotal, rs.estFee)
1330					if !ok {
1331						t.Fatalf("test setup: reserved sum overflow")
1332					}
1333					reservedTotal = sum
1334					sum, ok = addInt64(accountReserved, rs.estFee)
1335					if !ok {
1336						t.Fatalf("test setup: account reserved overflow")
1337					}
1338					accountReserved = sum
1339				case RequestSettled:
1340					sum, ok := addInt64(spentTotal, rs.actualFee)
1341					if !ok {
1342						t.Fatalf("test setup: spent sum overflow")
1343					}
1344					spentTotal = sum
1345				}
1346			}
1347			for i := range b.Policies {
1348				if b.Policies[i].ID == ps.id {
1349					b.Policies[i].ReservedTotal = reservedTotal
1350					b.Policies[i].SpentTotal = spentTotal
1351				}
1352			}
1353		}
1354		for i := range b.Accounts {
1355			if b.Accounts[i].ID == "payer" {
1356				b.Accounts[i].Reserved = accountReserved
1357			}
1358		}
1359		data, err := json.Marshal(&b)
1360		if err != nil {
1361			t.Fatal(err)
1362		}
1363		return data
1364	}
