1421							{id: "s1", account: "u1", estFee: 30, actualFee: 20, state: RequestSettled},
1422							{id: "r1", account: "u1", estFee: 30, state: RequestReserved},
1423						},
1424					},
1425					{
1426						id: "p2", per: 100, total: 50,
1427						reqs: []quotaReqSpec{
1428							{id: "s2", account: "u1", estFee: 30, actualFee: 21, state: RequestSettled},
1429							{id: "r2", account: "u1", estFee: 30, state: RequestReserved},
1430						},
1431					},
1432				},
1433				restoreAt:  t0,
1434				wantPolicy: "p2",
1435			},
1436		}
1437		for _, tc := range cases {
1438			t.Run(tc.name, func(t *testing.T) {
1439				data := buildCumulativeQuotaBackup(t, t0, tc.policies)
1440				w2, err := restoreAt(data, tc.restoreAt)
1441				if err == nil {
