1450				msg := err.Error()
1451				if !strings.Contains(msg, tc.wantPolicy) {
1452					t.Fatalf("error %q must name policy %q", msg, tc.wantPolicy)
1453				}
1454				if !strings.Contains(msg, "cumulative total limit") {
1455					t.Fatalf("error %q must explain the cumulative total limit", msg)
1456				}
1457			})
1458		}
1459	}
1460	
1461	// TestRestoreRejectsPolicyCumulativeQuotaOverflow 验证预留与已花费各自都能
1462	// 由 int64 表示、合计却越过 int64 上限时必须拒绝，不能因金额越界误判为
1463	// 额度充足。
1464	func TestRestoreRejectsPolicyCumulativeQuotaOverflow(t *testing.T) {
1465		t0 := time.Date(2026, 1, 1, 12, 0, 0, 0, time.UTC)
1466		data := buildCumulativeQuotaBackup(t, t0, []quotaPolicySpec{{
1467			id: "p-big", per: math.MaxInt64, total: math.MaxInt64,
1468			reqs: []quotaReqSpec{
1469				{id: "settled", account: "u1", estFee: math.MaxInt64, actualFee: math.MaxInt64, state: RequestSettled},
1470				{id: "reserved", account: "u1", estFee: 1, state: RequestReserved},
1471			},
1472		}})
1473		w2, err := restoreAt(data, t0)
1474		if err == nil {
1475			if w2 != nil {
1476				t.Fatalf("overflowing-quota backup restored a wallet")
1477			}
1478			t.Fatalf("overflowing-quota backup restored without error")
1479		}
1480		if !errors.Is(err, ErrBackupInvalid) {
1481			t.Fatalf("err = %v, want ErrBackupInvalid", err)
1482		}
1483		msg := err.Error()
1484		if !strings.Contains(msg, "p-big") || !strings.Contains(msg, "cumulative total limit") {
1485			t.Fatalf("error %q must name policy and cumulative limit", msg)
1486		}
1487	}
1488	
1489	// TestRestoreAcceptsCumulativeQuotaAtBoundary 验证合计恰好等于累计上限合法，
1490	// 包括上限恰为 int64 最大值的情况；不缩小现有金额范围。
1491	func TestRestoreAcceptsCumulativeQuotaAtBoundary(t *testing.T) {
1492		t0 := time.Date(2026, 1, 1, 12, 0, 0, 0, time.UTC)
1493	
1494		// 上限 50：结算实际 20（预估 30，差额已退回）+ 现存预留 30 = 50。
1495		data := buildCumulativeQuotaBackup(t, t0, []quotaPolicySpec{{
1496			id: "p-eq", per: 30, total: 50,
1497			reqs: []quotaReqSpec{
1498				{id: "settled", account: "u1", estFee: 30, actualFee: 20, state: RequestSettled},
1499				{id: "reserved", account: "u1", estFee: 30, state: RequestReserved},
1500			},
1501		}})
1502		if _, err := restoreAt(data, t0); err != nil {
1503			t.Fatalf("used == total restore: %v", err)
1504		}
1505	
1506		// 上限 MaxInt64：已花费 MaxInt64-1 + 预留 1 = MaxInt64。
1507		data = buildCumulativeQuotaBackup(t, t0, []quotaPolicySpec{{
1508			id: "p-max", per: math.MaxInt64, total: math.MaxInt64,
1509			reqs: []quotaReqSpec{
1510				{id: "settled", account: "u1", estFee: math.MaxInt64, actualFee: math.MaxInt64 - 1, state: RequestSettled},
1511				{id: "reserved", account: "u1", estFee: 1, state: RequestReserved},
1512			},
1513		}})
1514		if _, err := restoreAt(data, t0); err != nil {
1515			t.Fatalf("used == MaxInt64 restore: %v", err)
1516		}
1517	
1518		// 上限 MaxInt64：单笔已结算实际费用 MaxInt64，占满额度。
1519		data = buildCumulativeQuotaBackup(t, t0, []quotaPolicySpec{{
1520			id: "p-spent-max", per: math.MaxInt64, total: math.MaxInt64,
1521			reqs: []quotaReqSpec{
1522				{id: "settled", account: "u1", estFee: math.MaxInt64, actualFee: math.MaxInt64, state: RequestSettled},
1523			},
1524		}})
1525		if _, err := restoreAt(data, t0); err != nil {
1526			t.Fatalf("spent == MaxInt64 restore: %v", err)
1527		}
1528	
1529		// 上限 MaxInt64：单笔预估费用 MaxInt64 的现存预留占满额度。
1530		data = buildCumulativeQuotaBackup(t, t0, []quotaPolicySpec{{
1531			id: "p-reserved-max", per: math.MaxInt64, total: math.MaxInt64,
1532			reqs: []quotaReqSpec{
1533				{id: "reserved", account: "u1", estFee: math.MaxInt64, state: RequestReserved},
1534			},
1535		}})
1536		if _, err := restoreAt(data, t0); err != nil {
1537			t.Fatalf("reserved == MaxInt64 restore: %v", err)
1538		}
1539	
1540		// 不同策略分别判断：同一出资账户的两条策略各自恰好占满 50，
1541		// 跨策略合计 100 不影响合法性。
1542		data = buildCumulativeQuotaBackup(t, t0, []quotaPolicySpec{
1543			{
1544				id: "p1", per: 100, total: 50,
1545				reqs: []quotaReqSpec{
1546					{id: "s1", account: "u1", estFee: 30, actualFee: 20, state: RequestSettled},
1547					{id: "r1", account: "u1", estFee: 30, state: RequestReserved},
1548				},
1549			},
1550			{
1551				id: "p2", per: 100, total: 50,
1552				reqs: []quotaReqSpec{
1553					{id: "s2", account: "u2", estFee: 30, actualFee: 20, state: RequestSettled},
1554					{id: "r2", account: "u2", estFee: 30, state: RequestReserved},
1555				},
1556			},
1557		})
1558		if _, err := restoreAt(data, t0); err != nil {
1559			t.Fatalf("two policies each at their own limit: %v", err)
1560		}
1561	}
1562	
1563	// TestRestoreCumulativeQuotaIgnoresNonOccupyingStates 验证只有现存预留与已
1564	// 结算实际费用占用累计额度：待审批、审批拒绝、待审批取消、待审批过期、已
1565	// 预留后取消、预留超时的请求都不占用；结算退回的差额也不计入已花费。
1566	func TestRestoreCumulativeQuotaIgnoresNonOccupyingStates(t *testing.T) {
1567		t0 := time.Date(2026, 1, 1, 12, 0, 0, 0, time.UTC)
1568		// 累计上限仅 10：一笔实际费用 10 的已结算请求占满额度；其余请求费用均
1569		// 为 30（待审批系严格超过门槛 10），但都不占用额度，备份仍合法。
1570		data := buildCumulativeQuotaBackup(t, t0, []quotaPolicySpec{{
1571			id: "p-free", per: 100, total: 10, threshold: 10,
1572			wait: 5 * time.Minute, reserveDur: time.Minute,
1573			reqs: []quotaReqSpec{
1574				{id: "settled", account: "u1", estFee: 10, actualFee: 10, state: RequestSettled},
1575				{id: "reserved-cancelled", account: "u1", estFee: 10, state: RequestCancelled, wasReserved: true},
1576				{id: "reservation-expired", account: "u1", estFee: 10, state: RequestReservationExpired},
1577				{id: "pending", account: "u1", estFee: 30, state: RequestPendingApproval},
1578				{id: "rejected", account: "u1", estFee: 30, state: RequestRejected, rejectReason: "no"},
1579				{id: "pending-expired", account: "u1", estFee: 30, state: RequestExpired},
1580				{id: "pending-cancelled", account: "u1", estFee: 30, state: RequestCancelled},
1581			},
1582		}})
1583		w2, err := restoreAt(data, t0)
1584		if err != nil {
1585			t.Fatalf("non-counting states restore: %v", err)
1586		}
1587		// 未到期的待审批请求不被改写；没有任何现存预留，账户预留余额为零。
1588		r, err := w2.Request("u1", "pending")
1589		if err != nil || r.State != RequestPendingApproval {
1590			t.Fatalf("pending request state = %v err = %v, want still pending", r.State, err)
1591		}
1592		if bal, _ := w2.Balance("payer"); bal != (Balances{Available: 0, Reserved: 0}) {
1593			t.Fatalf("payer balance = %+v, want zero reserved", bal)
1594		}
1595	}
1596	
1597	// ---- 并发 ----
1598	
1599	func TestExportConcurrentWithMutations(t *testing.T) {
1600		w, c := newTestWallet()
1601		t0 := c.t
1602		mustAccount(t, w, "payer", 1_000_000)
1603		mustAccount(t, w, "u1", 0)
1604		mustAccount(t, w, "u2", 0)
1605		if _, err := w.CreateSession("s1", "u1", "dev1", t0.Add(24*time.Hour)); err != nil {
1606			t.Fatal(err)
1607		}
1608		if _, err := w.CreateSession("s2", "u2", "dev2", t0.Add(24*time.Hour)); err != nil {
1609			t.Fatal(err)
1610		}
1611		if err := w.SavePolicy(PolicySpec{
1612			ID: "p1", PayerAccountID: "payer", AllowedAccountIDs: []string{"u1", "u2"},
1613			Operation: "charge", Payee: "shop",
1614			StartsAt: t0.Add(-time.Hour), EndsAt: t0.Add(24 * time.Hour),
1615			MaxPerRequest: 100, MaxTotal: 1_000_000,
1616			MaxReserveDuration: time.Hour,
1617		}); err != nil {
1618			t.Fatal(err)
1619		}
1620	
1621		const n = 200
1622		var wg sync.WaitGroup
1623		var backups [][]byte
1624		var mu sync.Mutex
1625	
1626		// 申请/结算/取消/导出 并发；每个备份都必须是可恢复的完整状态。
1627		for g := 0; g < 4; g++ {
1628			g := g
1629			wg.Add(1)
1630			go func() {
1631				defer wg.Done()
1632				for i := 0; i < n; i++ {
1633					rid := fmt.Sprintf("g%d-r%d", g, i)
1634					in := RequestInput{
1635						PolicyID: "p1", RequestID: rid, AccountID: "u2", SessionID: "s2",
1636						DeviceID: "dev2", Operation: "charge", Payee: "shop", EstimatedFee: 1,
1637					}
1638					if _, err := w.Apply(in); err != nil {
1639						t.Errorf("apply: %v", err)
1640						return
1641					}
1642					switch i % 3 {
1643					case 0:
1644						if _, err := w.Settle("u2", rid, 1); err != nil {
1645							t.Errorf("settle: %v", err)
1646						}
1647					case 1:
1648						if _, err := w.Cancel("u2", rid); err != nil {
1649							t.Errorf("cancel: %v", err)
1650						}
1651					}
1652				}
1653			}()
1654		}
1655		wg.Add(1)
1656		go func() {
1657			defer wg.Done()
1658			for i := 0; i < n; i++ {
1659				data, err := w.Export()
1660				if err != nil {
1661					t.Errorf("export: %v", err)
1662					return
1663				}
1664				mu.Lock()
1665				backups = append(backups, data)
1666				mu.Unlock()
1667			}
1668		}()
1669		wg.Wait()
1670	
1671		if len(backups) == 0 {
1672			t.Fatal("no backups captured")
1673		}
1674		for i, data := range backups {
1675			w2, err := Restore(data)
1676			if err != nil {
1677				t.Fatalf("backup %d not restorable: %v", i, err)
1678			}
1679			// 恢复出的钱包余额自洽：非负且预留不凭空消失。
1680			for _, id := range []string{"payer"} {
1681				bal, err := w2.Balance(id)
1682				if err != nil {
1683					t.Fatalf("backup %d balance: %v", i, err)
1684				}
1685				if bal.Available < 0 || bal.Reserved < 0 {
1686					t.Fatalf("backup %d negative balance: %+v", i, bal)
1687				}
1688			}
1689		}
1690	
1691		// 最终状态本身也必须可导出/恢复且账本完整（用与源钱包相同的受控时刻，
1692		// 避免恢复时钟把未到期预留结算掉而混淆比较）。
1693		final, err := w.Export()
1694		if err != nil {
1695			t.Fatal(err)
1696		}
1697		w2, err := restoreAt(final, c.t)
1698		if err != nil {
1699			t.Fatal(err)
1700		}
1701		if l1, l2 := len(w.Ledger()), len(w2.Ledger()); l1 != l2 {
1702			t.Fatalf("final ledger length = %d, want %d", l2, l1)
1703		}
1704	}
1705

