874	// pendingWaitExpiredReason 是待审批请求到达等待截止时间、进入等待过期终态时
875	// 统一使用的过期原因。查询惰性过期、吊销申请会话、停用所属策略与导出/恢复
876	// 都共用这一文本，不因触发方式不同而变化。
877	const pendingWaitExpiredReason = "approval period expired"
878	
879	// pendingWaitTrigger 描述“结束等待”的触发方式。三种入口都以每笔请求自己的
880	// 等待截止时间为准：当前时刻严格早于截止时间时是否按触发方式拒绝，由
881	// rejectEarly 区分（查询不拒绝、继续等待；吊销会话与停用策略拒绝）；恰到
882	// 截止时间及之后三者统一进入等待过期终态。拒绝时写入请求与拒绝留痕的理由、
883	// 审批账户由各触发方式提供，等待过期的口径三者一致。
884	type pendingWaitTrigger interface {
885		// rejectEarly 表示严格早于等待截止时间时是否立即拒绝待审批请求。
886		rejectEarly() bool
887		// rejectReason 返回截止前拒绝时写入请求与拒绝留痕的理由。
888		rejectReason(req *request) string
889		// rejectApprover 返回截止前拒绝记录的审批账户；空串表示不填写。
890		rejectApprover(req *request) string
891	}
892	
893	// pendingWaitOutcome 以请求自己的等待截止时间为准返回当前结果，不改变状态：
894	// 非待审批请求返回空串；严格早于截止时间时，rejectEarly 为真返回 "reject"，
895	// 否则返回空串（继续等待，不产生审批决定或过期记录）；恰到截止时间及之后
896	// 返回 "expire"。终态请求一律返回空串，因此已批准预留、已拒绝、已取消、已
897	// 过期等都不会被改写成等待过期。
898	func pendingWaitOutcome(req *request, now time.Time, rejectEarly bool) string {
899		if req.state != RequestPendingApproval {
900			return ""
901		}
902		if now.Before(req.waitDeadline) {
903			if rejectEarly {
904				return "reject"
905			}
906			return ""
907		}
908		return "expire"
909	}
910	
911	// settlePendingWaitLocked 按触发方式结清单笔待审批请求的等待：仍在等待则
912	// 原样保留；截止前可拒绝的进入拒绝终态（理由与审批账户取自触发方式）；已到
913	// 或超过截止时间的进入等待过期终态（拒绝理由与审批账户均为空）。决定时间
914	// 一律记录本次处理时刻，提交时间与等待截止时间保持不变；账本只追加一条
915	// 关联使用账户与请求编号的零金额状态记录。任何资金余额、策略预留与已花费
916	// 总额都不变。必须在持锁状态下调用。
917	func (w *Wallet) settlePendingWaitLocked(req *request, now time.Time, trigger pendingWaitTrigger) {
918		switch pendingWaitOutcome(req, now, trigger.rejectEarly()) {
919		case "reject":
920			req.state = RequestRejected
921			req.rejectReason = trigger.rejectReason(req)
922			req.decidedAt = now
923			// 吊销会话不填写审批账户（返回空串）；停用策略填写出资账户。
924			if approver := trigger.rejectApprover(req); approver != "" {
925				req.approverAccountID = approver
926			}
927			w.ledger = append(w.ledger, LedgerEntry{
928				Kind:      LedgerRejection,
929				AccountID: req.accountID,
930				RequestID: req.requestID,
931				Reason:    req.rejectReason,
932				At:        now,
933			})
934		case "expire":
935			// 等待过期：不带任何拒绝原因、不填写审批账户，与查询惰性过期口径一致。
936			req.state = RequestExpired
937			req.decidedAt = now
938			w.ledger = append(w.ledger, LedgerEntry{
939				Kind:      LedgerExpiration,
940				AccountID: req.accountID,
941				RequestID: req.requestID,
942				Reason:    pendingWaitExpiredReason,
943				At:        now,
944			})
945		}
946	}
947	
948	// settlePendingWaitsLocked 按给定顺序逐笔结清待审批请求的等待。pending 通常
949	// 由 pendingWaitsLocked 系列收集器按等待截止时间排好序；一次操作涉及多笔
950	// 请求时，各笔只按自身的等待截止时间分别得到结果，互不影响。必须在持锁
951	// 状态下调用。
952	func (w *Wallet) settlePendingWaitsLocked(pending []*request, now time.Time, trigger pendingWaitTrigger) {
953		for _, req := range pending {
954			w.settlePendingWaitLocked(req, now, trigger)
955		}
956	}
957	
958	// sortPendingWaitsLocked 按等待截止时刻排序待审批请求（同截止时刻按使用
959	// 账户、请求编号排序），使多笔申请分别处理时账本追加顺序确定。三种入口共用
960	// 这套原先约定的批量处理顺序。
961	func sortPendingWaitsLocked(pending []*request) {
962		sort.SliceStable(pending, func(i, j int) bool {
963			if pending[i].waitDeadline.Equal(pending[j].waitDeadline) {
964				if pending[i].accountID != pending[j].accountID {
965					return pending[i].accountID < pending[j].accountID
966				}
967				return pending[i].requestID < pending[j].requestID
968			}
969			return pending[i].waitDeadline.Before(pending[j].waitDeadline)
970		})
971	}
972	
973	// pendingWaitsLocked 收集当前仍在待审批的请求，match 为 nil 时收集全部；
974	// 结果按等待截止时刻排序。必须在持锁状态下调用。
975	func (w *Wallet) pendingWaitsLocked(match func(*request) bool) []*request {
976		pending := make([]*request, 0)
977		for _, req := range w.requests {
978			if req.state != RequestPendingApproval {
979				continue
980			}
981			if match != nil && !match(req) {
982				continue
983			}
984			pending = append(pending, req)
985		}
986		sortPendingWaitsLocked(pending)
987		return pending
988	}
989	
990	// pendingWaitsBySessionLocked 收集某申请会话下仍在待审批的请求（按等待截止
991	// 时刻排序），供吊销会话时逐笔结清。必须在持锁状态下调用。
992	func (w *Wallet) pendingWaitsBySessionLocked(sessionID string) []*request {
993		return w.pendingWaitsLocked(func(req *request) bool { return req.sessionID == sessionID })

